  Fixpoint list_eqbZ (l1 l2 : list Z) : bool :=
    match l1, l2 with
    | [], [] => true
    | x :: r1, y :: r2 => (x =? y) && list_eqbZ r1 r2
    | _, _ => false
    end.
  Lemma list_eqbZ_eq : forall l1 l2, list_eqbZ l1 l2 = true -> l1 = l2.
Proof.
